html:
{#- Tax invoice in the style of the v14 POS_INVO_C1 + "LetterHead INV".
    With a Letter Head chosen, Frappe prints it above; without one, the company block below is used. -#}
{%- set company = frappe.get_cached_doc("Company", doc.company) -%}
{%- set customer = frappe.get_cached_doc("Customer", doc.customer) -%}
{%- set address = doc.shipping_address or doc.address_display -%}
<style>
	.ss-inv { font-size: 11px; color: #000; }
	.ss-inv .ss-company { font-family: serif; font-size: 16px; line-height: 1.25; margin-top: 12px; }
	.ss-inv .ss-logo { width: 70px; }
	.ss-inv .ss-title { text-align: right; margin-top: 18px; }
	.ss-inv .ss-title h2 { font-size: 22px; font-weight: 400; margin: 0; }
	.ss-inv .ss-title .ss-name { color: #888; font-size: 13px; margin-top: 18px; }
	.ss-inv hr { border: 0; border-top: 1px solid #d1d8dd; margin: 8px 0 14px; }
	.ss-inv .ss-info td { padding: 2px 4px; vertical-align: top; }
	.ss-inv .ss-label { font-weight: bold; width: 130px; }
	.ss-inv .ss-items { width: 100%; border-collapse: collapse; margin-top: 18px; }
	.ss-inv .ss-items th { background: #f0f0f0; color: #000; font-weight: bold; text-align: left; }
	.ss-inv .ss-items th, .ss-inv .ss-items td { border: 1px solid #d1d8dd; padding: 5px 6px; }
	.ss-inv .text-right { text-align: right; }
	.ss-inv .ss-totals { width: 50%; margin-left: 50%; margin-top: 8px; }
	.ss-inv .ss-totals td { padding: 4px 4px; vertical-align: top; }
	.ss-inv .ss-totals .ss-label { width: 45%; }
	.ss-inv .ss-grand td { font-weight: bold; font-size: 13px; }
	.ss-inv .ss-terms h3 { font-size: 15px; font-weight: bold; margin: 22px 0 18px; }
</style>
<div class="ss-inv">
	{%- if not letter_head %}
	<img class="ss-logo" src="{{ company.company_logo or '/assets/delivery_management/images/show-satellite-logo.png' }}">
	<div class="ss-company">
		Company: {{ company.company_name }}<br>
		{%- if company.tax_id %}VAT NO : {{ company.tax_id }}<br>{% endif %}
		{%- if company.registration_details %}CR: {{ company.registration_details }}{% endif %}
	</div>
	{%- endif %}

	<div class="ss-title">
		<h2>{{ _("TAX INVOICE") if not doc.is_return else _("CREDIT NOTE") }}</h2>
		<div class="ss-name">{{ doc.name }}</div>
	</div>
	<hr>

	<table class="ss-info" style="width: 100%">
		<tr>
			<td style="width: 50%">
				<table>
					<tr><td class="ss-label">{{ _("Customer Name") }}:</td><td><b style="font-size: 12px">{{ doc.customer_name }}</b></td></tr>
					<tr><td class="ss-label">{{ _("Mobile No") }}:</td><td>{{ doc.contact_mobile or customer.mobile_no or "" }}</td></tr>
					{%- if address %}
					<tr><td class="ss-label">{{ _("Shipping Address") }}:</td><td>{{ address }}</td></tr>
					{%- endif %}
					<tr><td class="ss-label">{{ _("TAX ID") }}:</td><td>{{ doc.tax_id or customer.tax_id or "N/A" }}</td></tr>
					{%- if doc.dm_ac_tech_name %}
					<tr><td class="ss-label">{{ _("AC Technician") }}:</td><td>{{ doc.dm_ac_tech_name }}</td></tr>
					<tr><td class="ss-label">{{ _("AC Technician Mobile") }}:</td><td>{{ doc.dm_ac_tech_mobile or "" }}</td></tr>
					{%- endif %}
				</table>
			</td>
			<td style="width: 50%">
				<table>
					<tr><td class="ss-label">{{ _("Date") }}:</td><td><b style="font-size: 12px">{{ frappe.utils.formatdate(doc.posting_date, "dd-MM-yyyy") }}</b></td></tr>
					<tr><td class="ss-label">{{ _("Posting Time") }}:</td><td>{{ frappe.utils.format_time(doc.posting_time, "HH:mm:ss") }}</td></tr>
					<tr><td class="ss-label">{{ _("Payment Due Date") }}:</td><td>{{ frappe.utils.formatdate(doc.due_date, "dd-MM-yyyy") }}</td></tr>
					<tr><td class="ss-label">{{ _("Status") }}:</td><td>{{ _(doc.status) }}</td></tr>
					<tr><td colspan="2">{{ _("Printed On") }}: {{ frappe.utils.format_datetime(frappe.utils.now(), "dd-MM-yyyy HH:mm:ss") }}</td></tr>
				</table>
			</td>
		</tr>
	</table>

	<table class="ss-items">
		<thead>
			<tr>
				<th style="width: 6%">{{ _("Sr") }}</th>
				<th>{{ _("Item") }}</th>
				<th class="text-right" style="width: 14%">{{ _("Quantity") }}</th>
				<th class="text-right" style="width: 15%">{{ _("Rate") }}</th>
				<th class="text-right" style="width: 15%">{{ _("Amount") }}</th>
			</tr>
		</thead>
		<tbody>
			{%- for row in doc.items %}
			<tr>
				<td>{{ row.idx }}</td>
				<td>{{ row.item_name }}</td>
				<td class="text-right">{{ row.get_formatted("qty", doc) }} {{ row.uom }}</td>
				<td class="text-right">{{ row.get_formatted("rate", doc) }}</td>
				<td class="text-right">{{ row.get_formatted("amount", doc) }}</td>
			</tr>
			{%- endfor %}
		</tbody>
	</table>

	<table class="ss-totals">
		<tr><td class="ss-label">{{ _("Total (Without Tax)") }}</td><td class="text-right">{{ doc.get_formatted("net_total") }}</td></tr>
		<tr><td class="ss-label">{{ _("Tax Category") }}:</td><td>{{ doc.tax_category or (doc.taxes[0].description if doc.taxes else "") }}</td></tr>
		<tr><td class="ss-label">{{ _("Total Taxes and Charges") }}:</td><td class="text-right">{{ doc.get_formatted("total_taxes_and_charges") }}</td></tr>
		<tr><td class="ss-label">{{ _("Additional Discount Amount") }}:</td><td class="text-right">{{ doc.get_formatted("discount_amount") }}</td></tr>
		<tr class="ss-grand"><td class="ss-label">{{ _("Grand Total") }}:</td><td class="text-right">{{ doc.get_formatted("rounded_total" if doc.rounded_total else "grand_total") }}</td></tr>
		<tr><td class="ss-label">{{ _("Outstanding Amount") }}:</td><td class="text-right">{{ doc.get_formatted("outstanding_amount") }}</td></tr>
		<tr><td class="ss-label">{{ _("In Words") }}:</td><td>{{ doc.in_words or "" }}</td></tr>
	</table>

	{%- if doc.posa_notes %}
	<table class="ss-info" style="margin-top: 14px">
		<tr><td class="ss-label">{{ _("Additional Notes") }}:</td><td>{{ doc.posa_notes | e | replace("\n", "<br>") }}</td></tr>
	</table>
	{%- endif %}

	<div class="ss-terms">
		<h3>{{ _("Terms & Conditions") }}</h3>
		<div>{{ doc.terms or _("Only warranty for the TV and Receiver We do not give any warranty for the accessories.") }}</div>
		<p style="margin-top: 28px">{{ _("Creator") }}:<br>{{ frappe.get_fullname(doc.owner) }}</p>
		<p style="text-align: center; margin-top: 18px">{{ _("Thank you, please visit again.") }}</p>
	</div>
</div>
